/* The runtime's symbol table, used by the interpreter to resolve `extern func` declarations. */
#define _GNU_SOURCE /* RTLD_DEFAULT */
#include "a0rt.h"

#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#ifdef _MSC_VER
/* With optimization these are intrinsics, and an intrinsic's address is not a constant initializer. */
#pragma function(floor, ceil, log2)
#endif

#ifdef __wasm__
/* Calling a function through a pointer of another type traps in WebAssembly, so the table holds
 * wrappers that take the interpreter's 64-bit words (generated by build.rs). */
#include "ffi_wrappers.h"
#define SYM(f) {#f, (void *)&a0_w_##f}
#else
#define SYM(f) {#f, (void *)&f}
#endif

